sys_variable_value.value:
(function(outputs, steps, stepResult, assertEqual)
{
	var test = new x_snc_devtools.TestAPI(outputs, steps, stepResult, assertEqual);
	
	test.SetResult(true);
	
	function TestCase_DependencyTreeGetMermaid(dependency_tree,vExpected)
	{
		function TestCase_DependencyTreeGetMermaid_CheckResult(vInput,vExpected,vResult)
		{
			if (vExpected == false)
			{
				return (vExpected == vResult);	
			}
			var strCode = GetStringValue(vResult);
			if (strCode.indexOf('stateDiagram-v2\n') == -1)
			{
				return false;
			}
			if (strCode.indexOf('[*] -->') != -1)
			{
				return false;
			}
			if (strCode.indexOf('--> [*]') != -1)
			{
				return false;
			}
					
			return true;
		}
		
		test.TestCase(
			'Function DependencyTreeGetMermaid()',
			DependencyTreeGetMermaid,
			{
				'dependency_tree': dependency_tree
			},
			vExpected,
			TestCase_DependencyTreeGetMermaid_CheckResult);
	}
		
	TestCase_DependencyTreeGetMermaid(null,false);
	

	var dependency_tree = {
		name: 'Platform',
		//sys_id: '1',
		_dependencies: [
			{
				name: 'Portal UI',
				//sys_id: '2',
				compatible_versions: '1.0.0',
				_dependencies: [
					{
						name: 'Incident Management',
						//sys_id: '3',
						compatible_versions: '1.2.0',
						_dependencies: [
							{
								name: 'ITSM Core',
								//sys_id: '3',
								compatible_versions: '2.0.0'
							}
						]
					},
					{
						name: 'Problem Management',
						//sys_id: '3',
						compatible_versions: '1.2.0',
						_dependencies: [
							{
								name: 'ITSM Core',
								//sys_id: '3',
								compatible_versions: '2.1.0',
								_dependencies: [
									{
										name: 'DevTools',
										//sys_id: '3',
										compatible_versions: '1.148.0'
									}
								]
							}
						]
					}
				]
			},
			{
				name: 'Mobile UI',
				compatible_versions: '1.1.0'
			}
		]
	};

	TestCase_DependencyTreeGetMermaid(dependency_tree,true);

	return test.GetResult();
	
})(outputs, steps, stepResult, assertEqual);
